solution.solution.rs:
mod bank {
    #[derive(Debug, PartialEq)]
    pub enum BankError {
        InvalidAmount,
        InsufficientFunds { needed: u64, available: u64 },
        SameAccount,
    }

    pub struct Account {
        id: u32,
        owner: String,
        balance: u64,
    }

    impl Account {
        pub fn open(id: u32, owner: &str) -> Account {
            Account { id, owner: owner.to_string(), balance: 0 }
        }

        pub fn id(&self) -> u32 { self.id }
        pub fn owner(&self) -> &str { &self.owner }
        pub fn balance(&self) -> u64 { self.balance }

        pub fn deposit(&mut self, cents: u64) -> Result<(), BankError> {
            if cents == 0 {
                return Err(BankError::InvalidAmount);
            }
            self.balance += cents;
            Ok(())
        }

        pub fn withdraw(&mut self, cents: u64) -> Result<(), BankError> {
            if cents == 0 {
                return Err(BankError::InvalidAmount);
            }
            if cents > self.balance {
                return Err(BankError::InsufficientFunds { needed: cents, available: self.balance });
            }
            self.balance -= cents;
            Ok(())
        }
    }

    pub fn transfer(from: &mut Account, to: &mut Account, cents: u64) -> Result<(), BankError> {
        if from.id == to.id {
            return Err(BankError::SameAccount);
        }
        from.withdraw(cents)?;
        to.deposit(cents)?;
        Ok(())
    }

    pub mod report {
        pub fn summary(accounts: &[super::Account]) -> String {
            let total: u64 = accounts.iter().map(|a| a.balance()).sum();
            format!("{} accounts, total {}.{:02}", accounts.len(), total / 100, total % 100)
        }
    }
}

unitTests:
use bank::{Account, BankError};

test("deposits and withdrawals", || {
    let mut a = Account::open(1, "Ada");
    check_eq(a.deposit(5000), Ok(()));
    check_eq(a.withdraw(1999), Ok(()));
    check_eq(a.balance(), 3001);
    check_eq(a.withdraw(4000), Err(BankError::InsufficientFunds { needed: 4000, available: 3001 }));
    check_eq(a.deposit(0), Err(BankError::InvalidAmount));
    check_eq(a.balance(), 3001);
    check_eq((a.id(), a.owner()), (1, "Ada"));
});

test("transfers", || {
    let mut a = Account::open(1, "Ada");
    let mut b = Account::open(2, "Bob");
    a.deposit(1000).unwrap();
    check_eq(bank::transfer(&mut a, &mut b, 250), Ok(()));
    check_eq((a.balance(), b.balance()), (750, 250));
    check_eq(bank::transfer(&mut a, &mut b, 5000), Err(BankError::InsufficientFunds { needed: 5000, available: 750 }));
    check_eq((a.balance(), b.balance()), (750, 250));
    let mut twin = Account::open(1, "Also Ada");
    check_eq(bank::transfer(&mut a, &mut twin, 10), Err(BankError::SameAccount));
    check_eq(bank::transfer(&mut a, &mut b, 0), Err(BankError::InvalidAmount));
});

test("summary from a nested module", || {
    let mut accounts = vec![Account::open(1, "A"), Account::open(2, "B"), Account::open(3, "C")];
    accounts[0].deposit(1000).unwrap();
    accounts[2].deposit(234).unwrap();
    check_eq(bank::report::summary(&accounts), "3 accounts, total 12.34");
    check_eq(bank::report::summary(&[]), "0 accounts, total 0.00");
});

